#!/usr/bin/env python3
"""Inspect 32 PDF samples generated by MAGNISA in CI. Samples never use production data."""
import glob,json,re,subprocess,sys,xml.etree.ElementTree as ET
from pathlib import Path
base=Path("test-results")
files=sorted(glob.glob("test-results/pdf/*.pdf"))
(base/"previews").mkdir(parents=True,exist_ok=True)
results=[]
if len(files)!=32:
    raise SystemExit(f"Expected 32 generated PDF files, got {len(files)}")
for file in files:
    p=Path(file); errors=[]
    info=subprocess.check_output(["pdfinfo",file],text=True)
    match=re.search(r"Pages:\s+(\d+)",info)
    pages=int(match.group(1)) if match else 0
    if pages<1:errors.append("no pages")
    raw=subprocess.check_output(["pdftotext","-layout",file,"-"],text=True)
    if "ENTREPRISE DE TEST" not in raw:errors.append("company heading missing")
    if not p.name.startswith("report-") and "TEST-EXCLUSIVEMENT" not in raw:errors.append("document reference missing")
    bbox=subprocess.check_output(["pdftotext","-bbox",file,"-"],text=True)
    root=ET.fromstring(bbox)
    page_elements=[element for element in root.iter() if element.tag.endswith("page")]
    if len(page_elements)!=pages:errors.append("page count mismatch in text layer")
    page_words=[]
    for i,page in enumerate(page_elements,1):
        width=float(page.get("width","0"));height=float(page.get("height","0"))
        if abs(width-595.28)>3 or abs(height-841.89)>3:
            errors.append(f"page {i} not A4 ({width}x{height})")
        words=[element for element in page.iter() if element.tag.endswith("word")]
        page_words.append(len(words))
        if not words:errors.append(f"page {i} has no selectable text")
        for word in words:
            x0=float(word.get("xMin","-99"));x1=float(word.get("xMax","9999"))
            y0=float(word.get("yMin","-99"));y1=float(word.get("yMax","9999"))
            if x0<-1 or y0<-1 or x1>width+1 or y1>height+1:
                errors.append(f"text outside page {i}")
                break
    subprocess.run(["pdftoppm","-scale-to","900","-png",file,str(base/"previews"/p.stem)],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    results.append(dict(preset=p.stem,pages=pages,text_chars=len(raw),words_per_page=page_words,errors=errors))
report=dict(count=len(results),passed=sum(not x["errors"] for x in results),failed=sum(bool(x["errors"]) for x in results),results=results)
(base/"pdf-geometry-report.json").write_text(json.dumps(report,ensure_ascii=False,indent=2))
print(f"PDF visual geometry: {report['passed']}/{report['count']} passed")
for r in results:
    if r["errors"]:print(r["preset"],r["errors"])

# Verify logo insertion and suppression for all four supported families.
logo_results=[]
for file in sorted(glob.glob("test-results/logos/*.pdf")):
    p=Path(file)
    output=subprocess.check_output(["pdfimages","-list",file],text=True)
    images=[line.split() for line in output.splitlines() if re.match(r"^\s*\d+\s+\d+\s+image\s",line)]
    enabled=p.stem.endswith("-active")
    errors=[]
    if enabled and not images:errors.append("logo image absent")
    if not enabled and images:errors.append("logo should be hidden")
    if enabled and images:
        if int(images[0][3])!=180 or int(images[0][4])!=60:errors.append("logo source dimensions altered")
    subprocess.run(["pdftoppm","-f","1","-l","1","-singlefile","-scale-to","900","-png",file,str(base/"previews"/("logo-"+p.stem))],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    logo_results.append(dict(document=p.stem,images=len(images),errors=errors))
if len(logo_results)!=8:
    raise SystemExit(f"Expected eight logo PDF fixtures, got {len(logo_results)}")
(base/"pdf-logo-report.json").write_text(json.dumps(logo_results,ensure_ascii=False,indent=2))
if any(row["errors"] for row in logo_results):
    print("Logo QA failed",logo_results)
    sys.exit(1)
print("PDF logo QA: 8/8 passed (visible/hidden, source aspect ratio)")

if report["failed"]:sys.exit(1)
